impl Solution{pub fn merge_k_lists(mut v:Vec<Option<Box<ListNode>>>)->Option<Box<ListNode>>{fn m(a:Option<Box<ListNode>>,b:Option<Box<ListNode>>)->Option<Box<ListNode>>{match(a,b){(None,x)|(x,None)=>x,(Some(mut x),Some(mut y))=>if x.val<=y.val{x.next=m(x.next.take(),Some(y));Some(x)}else{y.next=m(Some(x),y.next.take());Some(y)}}}while v.len()>1{let mut n=vec![];let mut it=v.into_iter();loop{match it.next(){None=>break,Some(a)=>{let b=it.next().unwrap_or(None);n.push(m(a,b));}}}v=n;}v.pop().unwrap_or(None)}}
